import{_ as o,a0 as p,w as u,s as r,I as t,x as s,a1 as e,A as n,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"3 个 Linux 上的 SSH 图形界面工具 | LCTT x X-CMD","titleTemplate":false,"description":"3 个 Linux 上的 SSH 图形界面工具 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 个 Linux 上的 SSH 图形界面工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 个 Linux 上的 SSH 图形界面工具 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20181123 Three SSH GUI Tools for Linux","title":"3 个 Linux 上的 SSH 图形界面工具","tag":"201902","desc":""},"relativePath":"201902/20181123 Three SSH GUI Tools for Linux.md","filePath":"[post].md"}'),d={name:"201902/20181123 Three SSH GUI Tools for Linux.md"};function S(m,i,T,g,f,x){const l=p("Link");return u(),r("div",null,[i[27]||(i[27]=t("h1",{id:"_3-个-linux-上的-ssh-图形界面工具",tabindex:"-1"},[s("3 个 Linux 上的 SSH 图形界面工具 "),t("a",{class:"header-anchor",href:"#_3-个-linux-上的-ssh-图形界面工具","aria-label":"Permalink to “3 个 Linux 上的 SSH 图形界面工具”"},"​")],-1)),i[28]||(i[28]=t("blockquote",null,[t("p",null,"了解一下这三个用于 Linux 上的 SSH 图形界面工具。")],-1)),i[29]||(i[29]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh.jpg?itok=3UcXhJt7",alt:""})],-1)),i[30]||(i[30]=t("p",null,"在你担任 Linux 管理员的职业生涯中，你会使用 Secure Shell（SSH）远程连接到 Linux 服务器或桌面。可能你曾经在某些情况下，会同时 SSH 连接到多个 Linux 服务器。实际上，SSH 可能是 Linux 工具箱中最常用的工具之一。因此，你应该尽可能提高体验效率。对于许多管理员来说，没有什么比命令行更有效了。但是，有些用户更喜欢使用 GUI 工具，尤其是在从台式机连接到远程并在服务器上工作时。",-1)),i[31]||(i[31]=t("p",null,"如果你碰巧喜欢好的图形界面工具，你肯定很乐于了解一些 Linux 上优秀的 SSH 图形界面工具。让我们来看看这三个工具，看看它们中的一个（或多个）是否完全符合你的需求。",-1)),t("p",null,[i[1]||(i[1]=s("我将在 ",-1)),e(l,{href:"https://elementary.io/"},{default:n(()=>[...i[0]||(i[0]=[s("Elementary OS",-1)])]),_:1}),i[2]||(i[2]=s(" 上演示这些工具，但它们都可用于大多数主要发行版。",-1))]),i[32]||(i[32]=t("h3",{id:"putty",tabindex:"-1"},[s("PuTTY "),t("a",{class:"header-anchor",href:"#putty","aria-label":"Permalink to “PuTTY”"},"​")],-1)),t("p",null,[i[4]||(i[4]=s("已经有一些经验的人都知道 ",-1)),e(l,{href:"https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html"},{default:n(()=>[...i[3]||(i[3]=[s("PuTTY",-1)])]),_:1}),i[5]||(i[5]=s("。实际上，从 Windows 环境通过 SSH 连接到 Linux 服务器时，PuTTY 是事实上的标准工具。但 PuTTY 不仅适用于 Windows。事实上，通过标准软件库，PuTTY 也可以安装在 Linux 上。 PuTTY 的功能列表包括：",-1))]),i[33]||(i[33]=a('<ul><li>保存会话。</li><li>通过 IP 或主机名连接。</li><li>使用替代的 SSH 端口。</li><li>定义连接类型。</li><li>日志。</li><li>设置键盘、响铃、外观、连接等等。</li><li>配置本地和远程隧道。</li><li>支持代理。</li><li>支持 X11 隧道。</li></ul><p>PuTTY 图形工具主要是一种保存 SSH 会话的方法，因此可以更轻松地管理所有需要不断远程进出的各种 Linux 服务器和桌面。一旦连接成功，PuTTY 就会建立一个到 Linux 服务器的连接窗口，你将可以在其中工作。此时，你可能会有疑问，为什么不在终端窗口工作呢？对于一些人来说，保存会话的便利确实使 PuTTY 值得使用。</p><p>在 Linux 上安装 PuTTY 很简单。例如，你可以在基于 Debian 的发行版上运行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install -y putty</span></span></code></pre></div><p>安装后，你可以从桌面菜单运行 PuTTY 图形工具或运行命令 <code>putty</code>。在 PuTTY “Configuration” 窗口（图 1）中，在 “HostName (or IP address) ” 部分键入主机名或 IP 地址，配置 “Port”（如果不是默认值 22），从 “Connection type”中选择 SSH，然后单击“Open”。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_1.jpg?itok=DiNTz_wO" alt="PuTTY Connection" title="PuTTY Connection"></p><p><em>图 1：PuTTY 连接配置窗口</em></p><p>建立连接后，系统将提示你输入远程服务器上的用户凭据（图2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_2.jpg?itok=4ORsJlz3" alt="log in" title="log in"></p><p><em>图 2：使用 PuTTY 登录到远程服务器</em></p><p>要保存会话（以便你不必始终键入远程服务器信息），请填写主机名（或 IP 地址）、配置端口和连接类型，然后（在单击 “Open” 之前），在 “Saved Sessions” 部分的顶部文本区域中键入名称，然后单击 “Save”。这将保存会话的配置。若要连接到已保存的会话，请从 “Saved Sessions” 窗口中选择它，单击 “Load”，然后单击 “Open”。系统会提示你输入远程服务器上的远程凭据。</p><h3 id="easyssh" tabindex="-1">EasySSH <a class="header-anchor" href="#easyssh" aria-label="Permalink to “EasySSH”">​</a></h3>',12)),t("p",null,[i[7]||(i[7]=s("虽然 ",-1)),e(l,{href:"https://github.com/muriloventuroso/easyssh"},{default:n(()=>[...i[6]||(i[6]=[s("EasySSH",-1)])]),_:1}),i[8]||(i[8]=s(" 没有提供 PuTTY 中的那么多的配置选项，但它（顾名思义）非常容易使用。 EasySSH 的最佳功能之一是它提供了一个标签式界面，因此你可以打开多个 SSH 连接并在它们之间快速切换。EasySSH 的其他功能包括：",-1))]),i[34]||(i[34]=a(`<ul><li>分组（出于更好的体验效率，可以对标签进行分组）。</li><li>保存用户名、密码。</li><li>外观选项。</li><li>支持本地和远程隧道。</li></ul><p>在 Linux 桌面上安装 EasySSH 很简单，因为可以通过 Flatpak 安装应用程序（这意味着你必须在系统上安装 Flatpak）。安装 Flatpak 后，使用以下命令添加 EasySSH：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo flatpak install flathub com.github.muriloventuroso.easyssh</span></span></code></pre></div><p>用如下命令运行 EasySSH：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak run com.github.muriloventuroso.easyssh</span></span></code></pre></div><p>将会打开 EasySSH 应用程序，你可以单击左上角的 “+” 按钮。 在结果窗口（图 3）中，根据需要配置 SSH 连接。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_3.jpg?itok=bHC2zlda" alt="Adding a connection" title="Adding a connection"></p><p><em>图 3：在 EasySSH 中添加连接很简单</em></p><p>添加连接后，它将显示在主窗口的左侧导航中（图 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_4.jpg?itok=hhJzhRIg" alt="EasySSH" title="EasySSH"></p><p><em>图 4：EasySSH 主窗口</em></p><p>要在 EasySSH 连接到远程服务器，请从左侧导航栏中选择它，然后单击 “Connect” 按钮（图 5）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_5.jpg?itok=piFEFYTQ" alt="Connecting" title="Connecting"></p><p><em>图 5：用 EasySSH 连接到远程服务器</em></p><p>对于 EasySSH 的一个警告是你必须将用户名和密码保存在连接配置中（否则连接将失败）。这意味着任何有权访问运行 EasySSH 的桌面的人都可以在不知道密码的情况下远程访问你的服务器。因此，你必须始终记住在你离开时锁定桌面屏幕（并确保使用强密码）。否则服务器容易受到意外登录的影响。</p><h3 id="terminator" tabindex="-1">Terminator <a class="header-anchor" href="#terminator" aria-label="Permalink to “Terminator”">​</a></h3><p>（LCTT 译注：这个选择不符合本文主题，本节删节）</p><h3 id="termius" tabindex="-1">termius <a class="header-anchor" href="#termius" aria-label="Permalink to “termius”">​</a></h3><p>（LCTT 译注：本节是根据网友推荐补充的）</p>`,19)),t("p",null,[i[10]||(i[10]=s("termius 是一个商业版的 SSH、Telnet 和 Mosh 客户端，不是开源软件。支持包括 ",-1)),e(l,{href:"https://www.termius.com/linux"},{default:n(()=>[...i[9]||(i[9]=[s("Linux",-1)])]),_:1}),i[11]||(i[11]=s("、Windows、Mac、iOS 和安卓在内的各种操作系统。对于单一设备是免费的，支持多设备的白金账号需要按月付费。",-1))]),i[35]||(i[35]=t("h3",{id:"很少-但值得-的选择",tabindex:"-1"},[s("很少（但值得）的选择 "),t("a",{class:"header-anchor",href:"#很少-但值得-的选择","aria-label":"Permalink to “很少（但值得）的选择”"},"​")],-1)),i[36]||(i[36]=t("p",null,"Linux 上没有很多可用的 SSH 图形界面工具。为什么？因为大多数管理员更喜欢简单地打开终端窗口并使用标准命令行工具来远程访问其服务器。但是，如果你需要图形界面工具，则有两个可靠选项，可以更轻松地登录多台计算机。虽然对于那些寻找 SSH 图形界面工具的人来说只有不多的几个选择，但那些可用的工具当然值得你花时间。尝试其中一个，亲眼看看。",-1)),i[37]||(i[37]=t("hr",null,null,-1)),t("p",null,[i[13]||(i[13]=s("via: ",-1)),e(l,{href:"https://www.linux.com/blog/learn/intro-to-linux/2018/11/three-ssh-guis-linux"},{default:n(()=>[...i[12]||(i[12]=[s("https://www.linux.com/blog/learn/intro-to-linux/2018/11/three-ssh-guis-linux",-1)])]),_:1})]),t("p",null,[i[18]||(i[18]=s("作者：",-1)),e(l,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...i[14]||(i[14]=[s("Jack Wallen",-1)])]),_:1}),i[19]||(i[19]=s(" 选题：",-1)),e(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[15]||(i[15]=[s("lujun9972",-1)])]),_:1}),i[20]||(i[20]=s(" 译者：",-1)),e(l,{href:"https://github.com/wxy"},{default:n(()=>[...i[16]||(i[16]=[s("wxy",-1)])]),_:1}),i[21]||(i[21]=s(" 校对：",-1)),e(l,{href:"https://github.com/wxy"},{default:n(()=>[...i[17]||(i[17]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[24]||(i[24]=s("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[22]||(i[22]=[s("LCTT",-1)])]),_:1}),i[25]||(i[25]=s(" 原创编译，",-1)),e(l,{href:"https://linux.cn/"},{default:n(()=>[...i[23]||(i[23]=[s("Linux中国",-1)])]),_:1}),i[26]||(i[26]=s(" 荣誉推出",-1))])])}const y=o(d,[["render",S]]);export{k as __pageData,y as default};
